{"file_path":"tests/test_metrics.py","content":"import pytest

from sales_dashboard.loader import daily_conversion_counts, dedupe_sessions, parse_session_log
from sales_dashboard.metrics import (
    conversion_rate,
    conversion_rate_by_group,
    conversions_in_window,
    longest_conversion_streak,
    pooled_conversion_rate,
)
from sales_dashboard.report import campaign_summary, top_converting_groups


def test_conversion_rate_basic():
    assert conversion_rate([{"converted": True}, {"converted": False}]) == 0.5


def test_conversion_rate_counts_none_as_not_converted():
    assert conversion_rate([{"converted": True}, {"converted": None}]) == 0.5


def test_conversion_rate_empty():
    assert conversion_rate([]) == 0.0


def test_pooled_conversion_rate_equal_groups():
    groups = {"a": [{"converted": True}, {"converted": False}], "b": [{"converted": True}, {"converted": False}]}
    assert pooled_conversion_rate(groups) == 0.5


def test_pooled_conversion_rate_weights_sessions_not_groups():
    groups = {"a": [{"converted": True}], "b": [{"converted": False}] * 3, "empty": []}
    assert pooled_conversion_rate(groups) == 0.25


@pytest.mark.parametrize("groups", [{}, {"empty": []}])
def test_pooled_conversion_rate_no_sessions(groups):
    assert pooled_conversion_rate(groups) == 0.0


@pytest.mark.parametrize(("days", "expected"), [(0, 0), (2, 5), (5, 6)])
def test_conversions_in_window(days, expected):
    assert conversions_in_window([1, 2, 3], days) == expected


def test_parse_session_log_one_line():
    assert parse_session_log(["x1,3,1"]) == [{"id": "x1", "day": 3, "converted": True}]


def test_parse_session_log_strips_fields_and_skips_blank_and_comment_lines():
    events = parse_session_log(["", " \t\n", "  # comment", " x , 1 , 1 ", " y , 2 , 0 ", " z , 3 , "])
    assert events == [
        {"id": "x", "day": 1, "converted": True},
        {"id": "y", "day": 2, "converted": False},
        {"id": "z", "day": 3, "converted": None},
    ]


@pytest.mark.parametrize("line", ["x,1", "x,1,0,extra", "x,no-day,1"])
def test_parse_session_log_error_counts_skipped_lines(line):
    with pytest.raises(ValueError, match=r"\bline 4\b"):
        parse_session_log(["a,1,1", "", " # comment", line])


def test_dedupe_sessions_keeps_last_duplicate_and_sorts_by_day_then_id():
    old = {"id": "a", "day": 4, "converted": True}
    latest = {"id": "a", "day": 2, "converted": False}
    same_day = {"id": "b", "day": 2, "converted": True}
    earlier_day = {"id": "z", "day": 1, "converted": None}
    assert dedupe_sessions([old, same_day, latest, earlier_day]) == [earlier_day, latest, same_day]


def test_daily_conversion_counts_includes_zero_days_and_ignores_outside_range():
    events = parse_session_log(["a,0,1", "b,1,1", "c,1,1", "d,2,0", "e,3,", "f,4,1", "g,5,1"])
    assert daily_conversion_counts(events, 1, 4) == [2, 0, 0, 1]
    assert daily_conversion_counts(events, 4, 1) == []
    assert daily_conversion_counts([], 1, 2) == [0, 0]


def test_campaign_summary_basic():
    e = [{"id": "a", "day": 1, "converted": True}, {"id": "b", "day": 2, "converted": False}]
    assert campaign_summary({"g": e}, 1)["groups"] == 1


def test_campaign_summary_pools_rates_and_uses_calendar_days():
    events = parse_session_log(["a,1,1", "b,4,1", "c,6,0"])
    groups = {"small": events[:1], "large": events[1:], "empty": []}
    assert campaign_summary(groups, 2) == {"rate": 0.667, "recent": 0, "groups": 2}
    assert campaign_summary(groups, 3)["recent"] == 1
    assert campaign_summary(groups, 0)["recent"] == 0
    assert campaign_summary({"empty": []}, 3) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_converting_groups_breaks_ties_by_name_and_excludes_empty_groups():
    groups = {
        "z": [{"converted": True}, {"converted": None}],
        "empty": [],
        "a": [{"converted": True}, {"converted": False}],
        "best": [{"converted": True}],
        "zero": [{"converted": False}],
    }
    assert top_converting_groups(groups, 2) == ["best", "a"]
    assert top_converting_groups(groups, 10) == ["best", "a", "z", "zero"]


def test_conversion_rate_by_group_sorts_names_and_distinguishes_empty_groups():
    groups = {"z": [{"converted": False}], "b": [], "a": [{"converted": True}]}
    assert list(conversion_rate_by_group(groups).items()) == [("a", 1.0), ("b", None), ("z", 0.0)]


@pytest.mark.parametrize(("counts", "expected"), [([], 0), ([0, -1], 0), ([1, 2, 0, 3, -1, 4, 5, 6], 3)])
def test_longest_conversion_streak(counts, expected):
    assert longest_conversion_streak(counts) == expected
